package org.icu.sepsis.ai;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import com.fasterxml.jackson.databind.ObjectMapper;
class GuidelineVectorCacheTest {
 @TempDir Path dir;
 @Test void vectorsRoundTripWithoutPatientFactsAndDifferentRevisionCannotReuse() throws Exception {var vectors=Map.of("synthetic-guideline",new float[]{1,2});GuidelineVectorCache.write(dir,"source-model-revision",vectors);var read=GuidelineVectorCache.read(dir,"source-model-revision",vectors.keySet());assertArrayEquals(vectors.get("synthetic-guideline"),read.get("synthetic-guideline"));assertNull(GuidelineVectorCache.read(dir,"different-model",vectors.keySet()));assertNull(GuidelineVectorCache.read(dir,"source-model-revision",Set.of("new-chunk")));}
 @Test void corruptDimensionsAndZeroVectorsAreNotRestored() throws Exception {GuidelineVectorCache.write(dir,"bad",Map.of("a",new float[]{1,2},"b",new float[]{1}));assertNull(GuidelineVectorCache.read(dir,"bad",Set.of("a","b")));GuidelineVectorCache.write(dir,"zero",Map.of("a",new float[]{0,0}));assertNull(GuidelineVectorCache.read(dir,"zero",Set.of("a")));}
 @Test void restartRestoresWholeGuidelineIndexWithoutCallingEmbeddingAgain(){var config=AiAssistServiceTest.props(true,"http://synthetic-gateway.invalid","chat","","embedding",1000,2);var llm=mock(LlmClient.class);when(llm.embed(anyList(),anyInt())).thenAnswer(inv->{List<?> inputs=inv.getArgument(0);var out=new ArrayList<float[]>();for(Object ignored:inputs)out.add(new float[]{1,2,3});return out;});var first=new KnowledgeBase(config,llm,new ObjectMapper());first.vectorCacheDir=dir.toString();first.buildVectors();assertEquals("ready",first.vectorStatus());assertEquals("saved",first.vectorCacheStatus());clearInvocations(llm);var restored=new KnowledgeBase(config,llm,new ObjectMapper());restored.vectorCacheDir=dir.toString();restored.buildVectors();assertEquals("ready",restored.vectorStatus());assertEquals("restored",restored.vectorCacheStatus());verifyNoInteractions(llm);}
}
